    "description": "8月13日23时许，受贾鲁河上游来水和沙颍河倒灌顶托挤压影响，河南省周口市川汇区新北环桥下贾鲁河东岸堤坝出现溃口。应急管理部调派中国安能工程救援力量200人，携带动力舟桥、水陆两栖挖掘机、装载机等大型工程机械装备110台(套)，紧急驰援周口灾区。14日上午10时，以上力量已到达现场投入抢险救援工作。",
