    "description": "进入旅游旺季，中哈霍尔果斯国际边境合作中心边境游、跨境游、购物游吸引了大量国内外游客，日均进出超3万人次。据霍尔果斯出入境边防检查站统计，截至8月13日，今年中哈霍尔果斯国际边境合作中心入出园人员已突破500万人次，达到512万人次。 为应对大客流，合作中心联检大厅已全面开放32条人工查验通道和22条快捷查验通道。 作者：周生斌、吴志恒 摄制：李明 新华社音视频部制作",
    "content": "进入旅游旺季，中哈霍尔果斯国际边境合作中心边境游、跨境游、购物游吸引了大量国内外游客，日均进出超3万人次。据霍尔果斯出入境边防检查站统计，截至8月13日，今年中哈霍尔果斯国际边境合作中心入出园人员已突破500万人次，达到512万人次。 为应对大客流，合作中心联检大厅已全面开放32条人工查验通道和22条快捷查验通道。 作者：周生斌、吴志恒 摄制：李明 新华社音视频部制作"
