    "description": "新华社北京8月14日电（记者李明睿）据多家媒体报道，美国总统特朗普7月7日释放可能向土耳其出售F-35隐形战斗机信号后，一个多月以来相关计划未取得实质进展。 据美国旗语新闻社13日报道，土耳其装备俄制S-400防空系统是军售障碍之一。美国国会部分议员认为，土耳其只有放弃这一系统才能获得F-35战机。 美国联邦参议员里克·斯科特说，土耳其“只要仍持有S-400系统，就不能获得F-35战机”。 此外，以色列方面也公开反对这项军售。美国智库“…",
    "content": "新华社北京8月14日电（记者李明睿）据多家媒体报道，美国总统特朗普7月7日释放可能向土耳其出售F-35隐形战斗机信号后，一个多月以来相关计划未取得实质进展。 据美国旗语新闻社13日报道，土耳其装备俄制S-400防空系统是军售障碍之一。美国国会部分议员认为，土耳其只有放弃这一系统才能获得F-35战机。 美国联邦参议员里克·斯科特说，土耳其“只要仍持有S-400系统，就不能获得F-35战机”。 此外，以色列方面也公开反对这项军售。美国智库“保卫民主基金会”土耳其项目主任锡南·吉迪说，以色列正向美国国会一些议员施压，要求…"
