    "content": "5月19日，工人在磴口县境内的乌兰布和沙漠里治沙（无人机照片）。新华社记者 连振 摄 新华社呼和浩特8月14日电 题：内蒙古磴口探索“用沙”方式治理乌兰布和沙漠 新华社记者赵泽辉、李云平 艳阳下，在乌兰布和沙漠东缘国家电投易事特光伏+沙产业治理项目区，一排排光伏板架在沙地上。板下，一行行梭梭扎住流沙，沙子底下，埋着去年接种的苁蓉。 “空中光伏板，地上梭梭林，地下肉苁蓉。”内蒙古巴彦淖尔市磴口县防沙治沙局副局长姜龙文说，同一片沙子，现在分三层用。 磴口县地处黄河“几字弯”顶端，境内乌兰布和沙漠近427万亩，占县域总面…"
