    "description": "近日，汉学家史乐民之作《耗尽天府：茶马之路与宋朝的兴亡》在光启书局出版。该书系刘东、刘迎胜主编的“海路与陆路”丛书之一，由刘云军翻译。对中国读者来说，这是一本“旧书新译”，中文版在英文原版问世的35年后姗姗来迟。但作为《剑桥中国宋代史》主编、《宋元研究》杂志（Journal of Song-Yuan Studies）现任编辑史乐民的唯一专著，它值得一阅；它涉及的宋代财税政策、“国有企业”茶马司、国家对四川地方的治理、以茶马互市为体现的跨…",
    "content": "近日，汉学家史乐民之作《耗尽天府：茶马之路与宋朝的兴亡》在光启书局出版。该书系刘东、刘迎胜主编的“海路与陆路”丛书之一，由刘云军翻译。对中国读者来说，这是一本“旧书新译”，中文版在英文原版问世的35年后姗姗来迟。但作为《剑桥中国宋代史》主编、《宋元研究》杂志（ Journal of Song-Yuan Studies ）现任编辑史乐民的唯一专著，它值得一阅；它涉及的宋代财税政策、“国有企业”茶马司、国家对四川地方的治理、以茶马互市为体现的跨区域民族交流等议题，依旧具有现实意义。 在编辑出版该书的过程中，责任编辑肖峰…"
