    "content": "新华社北京8月14日电（记者鲍赫）记者14日从北京市科学技术委员会了解到，自2014年以来，北京市已累计认定发布21批次、超2万项新产品新技术新服务，促进了科技创新与产业发展深度融合。 作为最新一批成果，第21批次发布活动于日前举办，这是三新产品认定工作开展以来首次举办集中发布活动。该批次共认定新产品370个、新技术108个、新服务19个，以新一代信息技术、高端装备制造、医药健康三大领域为主，合计占比超七成。 据介绍，北京市三新产品认定工作自2014年启动，2024年完成政策修订升级，持续遴选原创性、颠覆性科创成果…"
