    "pub_date": "2026-08-14 14:03:15",
    "author": "",
    "description": "36氪获悉，8月14日，金山办公旗下AI办公智能体灵犀专业版宣布首发接入智谱GLM-5.3模型。用户在灵犀专业版内切换至该模型即可直接使用，无需额外配置。接入GLM-5.3后，灵犀专业版在写代码、跑数据、处理复杂办公流程等代码驱动任务上的交付能力进一步增强，端到端完成工作的链路更完整。",
    "content": "36氪获悉，8月14日，金山办公旗下AI办公智能体灵犀专业版宣布首发接入智谱GLM-5.3模型。用户在灵犀专业版内切换至该模型即可直接使用，无需额外配置。接入GLM-5.3后，灵犀专业版在写代码、跑数据、处理复杂办公流程等代码驱动任务上的交付能力进一步增强，端到端完成工作的链路更完整。"
