    "description": "8月14日，智谱（2513.HK）发布GLM-5.3，与GLM-5.2相比，基座模型没变，但通过极致的后训练Scaling大大提高了模型的智能上界：数十倍的长程任务环境、更丰富多样的环境类型、超长的后训练时间。智谱表示，在多项主流基准测试中GLM-5.3是当前排名最高的开源模型，编程与智能体能力接近Claude Fable 5，编程体感超过其他国产模型。 智谱称，相比前代，GLM-5.3的新能力包括：更强的编程能力、网络安全能力、后训练…",
    "content": "8月14日，智谱（2513.HK）发布GLM-5.3，与GLM-5.2相比，基座模型没变，但通过极致的后训练Scaling大大提高了模型的智能上界：数十倍的长程任务环境、更丰富多样的环境类型、超长的后训练时间。智谱表示，在多项主流基准测试中GLM-5.3是当前排名最高的开源模型，编程与智能体能力接近Claude Fable 5，编程体感超过其他国产模型。 智谱称，相比前代，GLM-5.3的新能力包括：更强的编程能力、网络安全能力、后训练Scaling以及开源。 根据智谱介绍，在衡量模型于真实终端环境中完成复杂任务的…"
