    "content": "近日，多地博物馆展览、指引信息被游客指出存在错别字，引起舆论关注。 澎湃新闻记者注意到，有游客反映，在参观太原市博物馆《锦绣太原历史文化展》“并州来历”相关板块时发现，太原历代郡制变迁图文展板文字“项羽分天下诸王将，徒魏王豹为西魏王，都平阳(今山西临汾西)。徒赵王歇为代王，都代（今河北以太原郡二十一县及雁门墨守成辖县共三十一县为韩国，徒韩王信为韩王，都晋阳”中，疑似用字失误，将“徙”误写为“徒”。 8月14日上午，太原市博物馆工作人员接受澎湃新闻记者电话采访时承认，经陈展部门核实，展板标注中将“徙”错写为“徒”，文…"
