    "content": "核心内容 老父亲做装修的工人，个体，不属于任何公司组织下，一般就是微信群里或者认识的人来找介绍的装修的活。 总会遇到不清账。想法子扣钱的事情。 来问问大佬们有啥办法能把钱要下，这种个人对个人的之前咨询过劳动局管不了。让找法院。因为几百，几千去找法院。周期长，老爸一个人在老家也不会这些东西，也不值得找律师。所以就成了和死局一样的情况。 坐标山西四五线地级市的小地方 一直觉得政务差，个人觉得在我们那小地方没点关系办不了啥大事。这种事我感觉放在杭州很容易解决。 但也可能是我个人认识 可能在杭州也一样困难，只是我没碰到。 …"
