    "content": "8月13日上午，近百位读者在上海中心大厦门口排起长龙，他们皆为作家、编剧全勇先而来。 2026上海书展期间，由黑龙江省作家协会、人民文学出版社、世纪朵云联合主办的“鲁迅文学奖获奖作品《秘密》背后的故事——全勇先新书签售分享会”，在朵云书院·旗舰店举行。 全勇先新书《秘密》签售分享会现场 全勇先，1966 年生于黑龙江，中国作协会员、黑龙江省作协副主席。他的作品聚焦东北历史与人性刻画，兼具文学质感与影视表现力。深耕文学与影视创作数十年，他曾凭借谍战剧《悬崖》斩获白玉兰最佳编剧奖，与张艺谋合作编剧的电影《悬崖之上》亦广…"
