    "description": "新华社阿布扎比8月14日电（记者夏晓）阿联酋外交部14日凌晨发表声明称，阿布扎比国家石油公司两艘油轮通过霍尔木兹海峡时遭伊朗袭击。 声明还称，伊朗的袭击对地区稳定、民众安全以及全球能源安全造成威胁。 阿布扎比国家石油公司14日凌晨发布消息称，袭击发生于13日晚，未造成人员伤亡。 阿布扎比国家石油公司是阿联酋国有石油和天然气企业。阿联酋方面近期多次声称该国船只在通过霍尔木兹海峡时遭袭。",
    "content": "新华社阿布扎比8月14日电（记者夏晓）阿联酋外交部14日凌晨发表声明称，阿布扎比国家石油公司两艘油轮通过霍尔木兹海峡时遭伊朗袭击。 声明还称，伊朗的袭击对地区稳定、民众安全以及全球能源安全造成威胁。 阿布扎比国家石油公司14日凌晨发布消息称，袭击发生于13日晚，未造成人员伤亡。 阿布扎比国家石油公司是阿联酋国有石油和天然气企业。阿联酋方面近期多次声称该国船只在通过霍尔木兹海峡时遭袭。"
