    "description": "新华社长沙8月14日电 记者从湖南省涟源市应急管理局获悉，8月14日5时08分，涟源市杨梅山煤矿发生一起瓦斯突出事故。初步查明，当班入井作业人员52人，安全出井44人，失联7人，1人正在抢救。目前，当地已组织应急、卫健等相关部门现场开展应急救援处置工作，事故原因正在进一步调查。",
