    "content": "新华社北京8月14日电（记者郭倩）美国白宫网站13日发布消息说，总统特朗普当天签署一份国家安全总统备忘录，指示国防部重振舰船工业，解决舰船制造和维护方面的长期问题，并恢复产能和竞争力。 备忘录要求国防部以“芬兰模式”为基础，对美国造船业的工业基础加大直接投资。 白宫表示，“芬兰模式”首先被美国海岸警卫队的中型破冰船项目所采用。根据这一模式，如外国造船商对美国造船厂进行大量持久的投资，且由此创造工作岗位并培训美国劳动力，那么这些外国造船商将被暂时允许在其位于美国境外的母公司为美方建造最多两艘船。这些船将被快速交付以填…"
